export const meta = {
  name: 'ch-audit-run',
  description: 'Audit committed requirement patches against their requirement and deepen weak ones',
  whenToUse: 'After an implementation sweep, to catch no-op / shallow / incoherent diffs',
  phases: [
    { title: 'Audit' },
    { title: 'Repair' },
  ],
}

const input = args || {}
const slugs = Array.isArray(input) ? input : (input.slugs || [])

const AUDIT_SCHEMA = {
  type: 'object',
  properties: {
    slug: { type: 'string' },
    verdict: { type: 'string', enum: ['good', 'weak', 'wrong', 'missing'] },
    reason: { type: 'string' },
    fix_hint: { type: 'string' },
  },
  required: ['slug', 'verdict', 'reason'],
  additionalProperties: false,
}

const REPAIR_SCHEMA = {
  type: 'object',
  properties: {
    slug: { type: 'string' },
    committed: { type: 'boolean' },
    summary: { type: 'string' },
  },
  required: ['slug', 'committed', 'summary'],
  additionalProperties: false,
}

function auditPrompt(slug) {
  return `You are auditing ONE already-implemented requirement in the ClickHouse tree at /workspace.

slug: ${slug}
requirement: /workspace/requirements/${slug}.yaml
patch:       /workspace/requirement_patches/${slug}.diff

Read the requirement in full, then read the patch. Decide whether the patch genuinely satisfies the
requirement's "Desired outcome" and "Acceptance signals".

Verdicts:
- "good"    – the diff is a real, coherent change that plausibly matches what upstream ClickHouse did.
- "weak"    – the diff is real but shallow: it touches only a comment/doc when code was required, misses
              call sites, misses the test the acceptance signal describes, or covers one of several
              required occurrences.
- "wrong"   – the diff changes something unrelated to the requirement, or would not compile
              (missing include, removed symbol still referenced, mismatched signature, unbalanced braces).
- "missing" – the patch file is absent or effectively empty.

Be strict about compile coherence but do NOT try to build. Do NOT edit any files in this audit step.
Return JSON: slug, verdict, reason (1-3 sentences), fix_hint (concrete next action if not "good").`
}

function repairPrompt(slug, hint) {
  return `You are REPAIRING one requirement implementation in the ClickHouse tree at /workspace.

slug: ${slug}
requirement: /workspace/requirements/${slug}.yaml
existing patch: /workspace/requirement_patches/${slug}.diff  (already committed, do NOT revert it)

An audit judged the existing implementation insufficient:
${hint}

## Procedure
1. Read /workspace/requirements/${slug}.yaml and /workspace/agent_plans/SNAPSHOT_NOTES.md.
2. Read the already-committed diff so you build ON TOP of it instead of duplicating or reverting it.
3. Make the ADDITIONAL change that makes the requirement genuinely satisfied: the missing call sites,
   the missing occurrences of a wording fix, the stateless test the acceptance signal implies, the
   header include, the settings entry, the doc page. Match surrounding ClickHouse style exactly
   (4-space indent, Allman braces, \`/// \` doc comments).
4. Do NOT compile. Re-read your edit for syntax/type correctness instead.
5. Commit with:  /workspace/.agent_commit.sh ${slug} <repo-relative-path> [<path> ...]
   The helper appends to requirement_patches/${slug}.diff's history via a new commit; that is fine.
   It refuses an empty diff -- if it reports EMPTY DIFF you did not actually change anything, so make a
   real additional change and retry.

## Hard rules
- NEVER run git add / commit / checkout / reset / stash / restore / clean. Only the helper script.
- Other agents are editing OTHER files right now. Use the Edit tool on existing files, never Write.
- Touch only files in this requirement's scope. Never revert another agent's work.
- Do not edit /workspace/requirements/**, /workspace/requirement_patches/**, /workspace/agent_plans/**.

Return JSON: slug, committed (true only if helper printed OK), summary.`
}

phase('Audit')
log(`auditing ${slugs.length} committed requirements`)

const results = await pipeline(
  slugs,
  (slug) => agent(auditPrompt(slug), { label: `audit:${slug}`, phase: 'Audit', schema: AUDIT_SCHEMA }),
  (a, slug) => {
    if (!a || a.verdict === 'good') return { slug, verdict: a ? a.verdict : 'unknown', repaired: null }
    const hint = `verdict: ${a.verdict}\nreason: ${a.reason}\nsuggested fix: ${a.fix_hint || '(none given)'}`
    return agent(repairPrompt(slug, hint), { label: `repair:${slug}`, phase: 'Repair', schema: REPAIR_SCHEMA })
      .then(r => ({ slug, verdict: a.verdict, repaired: r && r.committed ? 'yes' : 'no' }))
      .catch(() => ({ slug, verdict: a.verdict, repaired: 'error' }))
  },
)

const rs = results.filter(Boolean)
const good = rs.filter(r => r.verdict === 'good')
const repaired = rs.filter(r => r.repaired === 'yes')
const stillBad = rs.filter(r => r.verdict !== 'good' && r.repaired !== 'yes')
log(`good ${good.length}, repaired ${repaired.length}, still weak ${stillBad.length}`)
return { good: good.length, repaired: repaired.map(r => r.slug), stillBad }

